{
    "type": "AdaptiveCard",
    "body": [
        {
            "type": "Container",
            "style": "emphasis",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "items": [
                                {
                                    "type": "Image",
                                    "weight": "Bolder",
                                    "text": "**Space Request**",
                                    "url": "data:image/png;base64,",
                                    "width": "60px",
                                    "height": "60px"
                                }
                            ],
                            "width": "60px",
                            "minHeight": "60px"
                        },
                        {
                            "type": "Column",
                            "items": [
                                {
                                    "type": "Container",
                                    "items": [
                                        {
                                            "type": "TextBlock",
                                            "text": "Provision Assist",
                                            "wrap": true,
                                            "horizontalAlignment": "Left",
                                            "size": "ExtraLarge",
                                            "weight": "Bolder"
                                        },
                                        {
                                            "type": "TextBlock",
                                            "text": "New Space Request 🆕",
                                            "wrap": true,
                                            "size": "Large",
                                            "horizontalAlignment": "Left"
                                        }
                                    ],
                                    "style": "default",
                                    "verticalContentAlignment": "Bottom"
                                }
                            ],
                            "width": "stretch",
                            "horizontalAlignment": "Center",
                            "verticalContentAlignment": "Bottom"
                        }
                    ]
                }
            ],
            "bleed": true,
            "backgroundImage": {
                "url": "data:image/png;base64,"
            }
        },
        {
            "type": "Container",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "size": "ExtraLarge",
                                    "text": "@{triggerBody()?['SpaceDisplayName']}",
                                    "wrap": true
                                }
                            ],
                            "width": "stretch"
                        },
                        {
                            "type": "Column",
                            "width": "auto"
                        }
                    ]
                },
                {
                    "type": "TextBlock",
                    "text": "A new space request has been submitted.",
                    "wrap": true,
                    "weight": "Bolder"
                },
                {
                    "type": "TextBlock",
                    "text": "Please approve or reject accordingly.",
                    "wrap": true
                },
                {
                    "type": "FactSet",
                    "spacing": "Large",
                    "facts": [
                        {
                            "title": "Requested By",
                            "value": "@{triggerBody()?['Author']?['DisplayName']}"
                        },
                        {
                            "title": "Submitted On",
                            "value": "@{triggerBody()?['Created']}"
                        },
                        {
                            "title": "Type",
                            "value": "@{triggerBody()?['SpaceType']?['Value']}"
                        },
                        {
                            "title": "Description",
                            "value": "@{triggerBody()?['Description']}"
                        },
                        {
                            "title": "Business Justification",
                            "value": "@{triggerBody()?['BusinessJustification']}"
                        },
                        {
                            "title": "Confidential Data",
                            "value": "@{if(equals(triggerBody()?['ConfidentialData'], false), 'No', 'Yes')}"
                        },
                        {
                            "title": "Visibility",
                            "value": "@{triggerBody()?['Visibility']?['Value']}"
                        }
                    ],
                    "separator": true
                }
            ]
        },
        {
            "type": "Container",
            "items": [
                {
                    "type": "TextBlock",
                    "text": "[View Request](@{triggerBody()?['{Link}']})",
                    "wrap": true
                },
                {
                    "type": "ActionSet",
                    "actions": [
                        {
                            "type": "Action.OpenUrl",
                            "title": "Chat with Requestor",
                            "url": "https://teams.microsoft.com/l/chat/0/0?users=@{triggerBody()?['Author']?['Email']}"
                        }
                    ]
                },
                {
                    "type": "ActionSet",
                    "actions": [
                        {
                            "type": "Action.ShowCard",
                            "title": "Approve",
                            "style": "positive",
                            "card": {
                                "type": "AdaptiveCard",
                                "body": [
                                    {
                                        "type": "Input.Text",
                                        "id": "approveComment",
                                        "placeholder": "Please specify an appropriate reason for approval.",
                                        "isMultiline": true
                                    }
                                ],
                                "actions": [
                                    {
                                        "type": "Action.Submit",
                                        "id": "Approve",
                                        "title": "Submit"
                                    }
                                ],
                                "$schema": "http://adaptivecards.io/schemas/adaptive-card.json"
                            }
                        },
                        {
                            "type": "Action.ShowCard",
                            "title": "Reject",
                            "style": "destructive",
                            "card": {
                                "type": "AdaptiveCard",
                                "body": [
                                    {
                                        "type": "Input.Text",
                                        "id": "rejectComment",
                                        "placeholder": "Please specify an appropriate reason for rejection.",
                                        "isMultiline": true
                                    }
                                ],
                                "actions": [
                                    {
                                        "type": "Action.Submit",
                                        "id": "Reject",
                                        "title": "Submit"
                                    }
                                ],
                                "$schema": "http://adaptivecards.io/schemas/adaptive-card.json"
                            }
                        }
                    ]
                }
            ]
        }
    ],
    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "version": "1.3",
    "fallbackText": "This card requires Adaptive Cards v1.2 support to be rendered properly."
}
